from ..templatesession import new_session
from .base_command import BaseCommand
from ..exception import BTSSMExecutionError, ErrorFoundInCommandLineOutput


class ClToolExecutor(BaseCommand):
    def __init__(self, config):
        super(ClToolExecutor, self).__init__()
        self._config = config

    def get_config(self):
        """ Returns config store """
        return self._config

    def execute_command(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute CLI tool operation except commissioning and swupdate
        :param string operation:  CLI tool operation used (i.e. upload bts file)
        :param string params:     Parameters needed for the CLI tool command
        :param string flags:      Optional parameters to be added
        :param string filename:   Filename of the file. If None, default filename will be used
        :param string filepath:   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = kwargs.get('timeout', 10)
        symlink = kwargs.get('symlink')
        with new_session.NewSession(alias, self._config, timeout=timeout) as session:
            if symlink:
                self._create_symlink_file(symlink, session)
            return self._run_shell_cmd(operation, flags, params, session, filename, filepath, trs_ip)

    def execute_commissioning(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute commissioning tool operation
        :param string operation:  CLI tool operation used (i.e. commissioning)
        :param dict   params:     Parameters needed for the CLI tool command
        :param list  flags:      Optional parameters to be added( i.e. waitforreset)
        :param string filename:   Filename of the file. If None, default filename will be used
        :param string filepath:   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used

        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = kwargs.get('timeout', 10)
        with new_session.NewSession(alias, self._config, timeout=timeout) as session:
            params = self._get_commissioning_params(params, session)
            return self._run_shell_cmd(operation, flags, params, session, filename, filepath, trs_ip)

    def execute_swupdate(self, operation, params, flags, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute sw update tool operation
        :param string operation:  CLI tool operation used (i.e. swupdate)
        :param dict   params:     Parameters needed for the CLI tool command
        :param list   flags:      Optional parameters to be added( i.e. waitforreset)
        :param string filename:   Filename of the file. If None, default filename will be used
        :param string filepath:   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = kwargs.get('timeout', 10)
        with new_session.NewSession(alias, self._config, timeout=timeout) as session:
            params['targetbd'] = session.executor.put_file(params['targetbd'], session.temp_dir)
            return self._run_shell_cmd(operation, flags, params, session, filename, filepath, trs_ip)

    def _run_shell_cmd(self, operation, flags, params, session, filename=None, filepath=None, trs_ip=None):
        cmd = session.cmd_builder.cl_tool.build(op=operation, params=params, flags=flags)
        try:
            session.executor.run_via_shell(cmd=cmd, op=operation)
        except (BTSSMExecutionError, ErrorFoundInCommandLineOutput) as e:
            self._collect_cli_error_log_files(config=self._config, session=session)
            raise e
        return self._path_to_collected_file(option=flags, executor=session.executor, log_path=session.log_path, trs_ip=trs_ip,
                                            filepath=filepath, filename=filename, host_ip=session.executor._ssh_conn_params.get('host'))
